Pipe    pipe_create( UInt8 elements , UInt8 element_size )
{
    UInt8 i ; 

    Pipe pipe = os_mem_request( sizeof( struct s_Pipe ) ) ; 

    if( pipe )
    {
        pipe->element_size = element_size ; 
    
        pipe->q_free       = q_create()   ;
        pipe->q_pennding   = q_create()   ;
    }


    for( i = 0 ; i < elements ; i ++ )
    {
        Pipe_Node *node = os_mem_request( sizeof( struct s_Pipe_Node ) ) ; 

        if( node )
        {
            node->data      = os_mem_request( element_size ) ; 

            q_insert( pipe->q_free , (Q_Msg *)node );
        }
    }

    return pipe ;
}

